PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" serial primary key not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" serial primary key not null, "name" varchar not null, "email" varchar, "email_verified_at" timestamp, "avatar" varchar, "google_email" varchar, "google_id" varchar, "google_token" varchar, "slack_email" varchar, "slack_id" varchar, "slack_token" varchar, "password" varchar, "remember_token" varchar, "created_at" timestamp, "updated_at" timestamp);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" timestamp, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" serial primary key not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" serial primary key not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" timestamp not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "projects" ("id" serial primary key not null, "name" varchar not null, "key" varchar not null, "owner_id" integer not null, "template" varchar not null, "members" integer not null, "created_at" timestamp, "updated_at" timestamp);
CREATE TABLE IF NOT EXISTS "project_members" ("id" serial primary key not null, "project_id" integer not null, "user_id" integer not null, "role" varchar not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "meetings" ("id" serial primary key not null, "title" varchar not null, "description" varchar, "link" varchar not null, "status" varchar not null default 'pending', "date" date not null, "start_time" timestamp not null, "end_time" timestamp not null, "project_id" integer not null, "creator_id" integer not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id") on delete cascade, foreign key("creator_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "activities" ("id" serial primary key not null, "description" varchar not null, "user_id" integer not null, "project_id" integer not null, "date" date not null, "update" varchar, "created_at" timestamp, "updated_at" timestamp, foreign key("user_id") references "users"("id") on delete cascade, foreign key("project_id") references "projects"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "meeting_participants" ("id" serial primary key not null, "meeting_id" integer not null, "user_id" integer not null, "status" varchar not null default 'on time', "created_at" timestamp, "updated_at" timestamp, foreign key("meeting_id") references "meetings"("id") on delete cascade, foreign key("user_id") references "project_members"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "repositories" ("id" serial primary key not null, "project_id" integer not null, "name" varchar not null, "url" varchar not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "meeting_summaries" ("id" serial primary key not null, "meeting_id" integer not null, "summary" varchar not null, "date" date not null, "created_at" timestamp, "updated_at" timestamp, foreign key("meeting_id") references "meetings"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "a_i_prompts_histories" ("id" serial primary key not null, "project_id" integer not null, "user_id" integer not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "a_i_prompts" ("id" serial primary key not null, "project_id" integer not null, "user_id" integer not null, "history_id" integer not null, "prompt" varchar not null, "response" varchar not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("history_id") references "a_i_prompts_histories"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "subtasks" ("id" serial primary key not null, "created_at" timestamp, "updated_at" timestamp);
CREATE TABLE IF NOT EXISTS "epics" ("id" serial primary key not null, "project_id" integer not null, "name" varchar not null, "description" text not null, "status" varchar not null, "progress_percent" integer not null, "key" varchar not null, "order" integer not null, "start_date" date not null, "end_date" date not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "backlogs" ("id" serial primary key not null, "title" varchar not null, "key" varchar not null, "description" varchar, "type" varchar not null default 'task', "status" varchar not null default 'to-do', "priority" varchar not null default 'low', "project_id" integer not null, "creator_id" integer not null, "epic_id" integer not null, "order" integer, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id") on delete cascade, foreign key("creator_id") references "project_members"("id") on delete cascade, foreign key("epic_id") references "epics"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sprints" ("id" serial primary key not null, "name" varchar not null, "epic_id" integer not null, "start_date" date not null, "end_date" date not null, "status" integer not null, "description" varchar, "created_at" timestamp, "updated_at" timestamp, foreign key("epic_id") references "epics"("id"));
CREATE TABLE IF NOT EXISTS "timelines" ("id" serial primary key not null, "project_id" integer not null, "date" date not null, "time" time not null, "name" varchar not null, "description" varchar not null, "user_id" integer not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id"), foreign key("user_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "task_attachments" ("id" serial primary key not null, "task_id" integer not null, "file_path" varchar not null, "file_name" varchar not null, "file_type" varchar not null, "file_size" varchar not null, "created_at" timestamp, "updated_at" timestamp, foreign key("task_id") references "backlogs"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "task_comments" ("id" serial primary key not null, "task_id" integer not null, "user_id" integer not null, "comment" text not null, "created_at" timestamp, "updated_at" timestamp, foreign key("task_id") references "backlogs"("id") on delete cascade, foreign key("user_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "task_assignees" ("id" serial primary key not null, "task_id" integer not null, "user_id" integer not null, "created_at" timestamp, "updated_at" timestamp, foreign key("task_id") references "backlogs"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "task_status_cols" ("id" serial primary key not null, "title" varchar not null, "project_id" integer not null, "created_at" timestamp, "updated_at" timestamp, foreign key("project_id") references "projects"("id"));
