CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_google_email_unique" on "users" ("google_email");
CREATE UNIQUE INDEX "users_google_id_unique" on "users" ("google_id");
CREATE UNIQUE INDEX "users_slack_email_unique" on "users" ("slack_email");
CREATE UNIQUE INDEX "users_slack_id_unique" on "users" ("slack_id");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "projects_owner_id_key_unique" on "projects" ("owner_id", "key");
CREATE UNIQUE INDEX "project_members_project_id_user_id_unique" on "project_members" ("project_id", "user_id");
CREATE UNIQUE INDEX "task_status_cols_project_id_title_unique" on "task_status_cols" ("project_id", "title");
COMMIT;
